mapper.select:
SELECT t.F_TRADE_ID outTradeId, /*外部成交编号*/ deal.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID secId, /**资产代码**/ zc.FINPROD_ABBR secAbbr,/**资产简称**/ t.TRADE_MARKET tradeMarket,/**交易场所**/ t.PS ps,/**交易方向**/ t.TRADE_ID tradeId,/**交易编号**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE settdateDate,/**交割日期**/ stl.SETTLE_DATE fundSettleDate,/**资金交收日**/ t.INV_AIM invAim,/**会计分类**/ t.CHL_ID chlId,/**通道代码**/ t.SHARE_AMT dealNum,/**成交数量**/ t.FPRICE_AMT fpriceAmt,/**全价总额**/ t.INT_AMT intAmt,/**应收利息总额**/ t.CCY ccy,/**币种**/ NVL(ttfd.FEE_AMT,0) brokerage,/**经手费**/ NVL(ttfd1.FEE_AMT,0) stlAmt,/**结算费**/ NVL(ttfd2.FEE_AMT,0) commissionPay,/**应付佣金**/ NVL(ttfd5.FEE_AMT,0) commission,/**净佣金**/ NVL(ttfd3.FEE_AMT,0) dealFeeAmt,/**交易手续费**/ NVL(ttfd4.FEE_AMT,0) stlFeeAmt,/**结算手续费**/ t.TRADE_AMT settleAmt,/**结算金额**/ t.FPRICE_AMT tradeAmt,/**本币交易金额**/ t.MY_ACCT_NO myAcctNo,/**资金账户**/ case when t.PS =#{PS_T04} then t.TRADE_AMT else 0 end entrustAmt,/**申购金额**/ case when t.PS =#{PS_T05} then t.TRADE_AMT else 0 end confirmAmt,/**中签金额**/ d.GEN_TYPE dataSource /**数据来源**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN TRD_PRODUCT_DEAL_ADD d on t.TRADE_ID = d.TRADE_ID LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal.BOOKSET_ID LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE =#{BUSI_TYPE_02} AND STL.ORDER_TYPE NOT LIKE 'N%' LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd ON ttfd.TRADE_ID = t.TRADE_ID AND ttfd.FEE_TYPE = #{FEE_TYPE_B01} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd1 ON ttfd1.TRADE_ID = t.TRADE_ID AND ttfd1.FEE_TYPE = #{FEE_TYPE_B07} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd2 ON ttfd2.TRADE_ID = t.TRADE_ID AND ttfd2.FEE_TYPE = #{FEE_TYPE_B05} and ttfd2.IS_PAY_WITH_TRADE=#{YES_NO_N} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd3 ON ttfd3.TRADE_ID = t.TRADE_ID AND ttfd3.FEE_TYPE = #{FEE_TYPE_B06} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd4 ON ttfd4.TRADE_ID = t.TRADE_ID AND ttfd4.FEE_TYPE = #{FEE_TYPE_B08} LEFT JOIN TRD_TRADE_FEE_DETAIL ttfd5 ON ttfd5.TRADE_ID = t.TRADE_ID AND ttfd5.FEE_TYPE = #{FEE_TYPE_B05} and ttfd2.IS_PAY_WITH_TRADE=#{YES_NO_Y} where t.BUSI_TYPE =#{BUSI_TYPE_02}
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal.BOOKSET_ID IN
#{finprodId}
and zc.FINPROD_ID IN
#{asset}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
AND t.TRADE_MARKET IN
#{tradeMarket}
AND d.GEN_TYPE IN
#{dataSource}
order by t.TRADE_ID desc

mapper.delete:
DELETE FROM BOK_DETAIL_ID
WHERE
 TRADE_ID = #{tradeId}

    AND BOOKSET_ID = #{booksetId}

mapper.select:
SELECT A.FINPROD_ID id, NVL(A.FINPROD_ABBR, A.FINPROD_NAME) text FROM FIN_PRODUCT A WHERE A.IS_CHL = #{Y} AND A.FINPROD_TYPE2 = #{F28}
AND A.FINPROD_ID = #{initValue}
AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT
,T2.CASH_TYPE_2 FROM FIN_CASH_PLAN T1, FIN_CASH_INFO T2 WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T1.PAY_DATE <= to_date(#{tradeDate},'yyyy-mm-dd')
ORDER BY T1.VDATE ASC
